<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rekapitulasi Survey</title><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#f5f6fa;font-family:system-ui;color:#202534}.wrap{max-width:1050px;margin:40px auto;padding:0 18px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.muted{color:#7b8395}.btn{display:inline-block;background:#5d5fe8;color:white;text-decoration:none;padding:11px 17px;border-radius:10px;font-weight:700}.stat{background:white;border-radius:17px;padding:22px;margin-bottom:18px;box-shadow:0 8px 30px rgba(30,40,80,.07)}.stat small{color:#7b8395}.stat strong{display:block;font-size:32px;margin-top:5px}.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.chart-card{background:#fff;border-radius:17px;padding:22px;box-shadow:0 8px 30px rgba(30,40,80,.07)}.chart-card h3{font-size:16px;line-height:1.4;margin:0 0 16px}.canvas{height:300px;position:relative}@media(max-width:760px){.chart-grid{grid-template-columns:1fr}.top{flex-direction:column;align-items:flex-start;gap:12px}}</style></head><body><div class="wrap"><div class="top"><div><h1>Rekapitulasi Survey</h1><div class="muted"><?= html_escape($survey->title) ?></div></div><a class="btn" href="<?= site_url('admin/survey/'.$survey->id.'/questions') ?>">← Kelola Pertanyaan</a></div><div class="stat"><small>Total Responden</small><strong><?= number_format($total) ?></strong></div><div class="chart-grid"><?php foreach($summary as $i=>$s): ?><div class="chart-card"><h3><?= ($i+1).'. '.html_escape($s['question']) ?></h3><div class="canvas"><canvas id="chart<?= $i ?>"></canvas></div></div><?php endforeach; ?></div></div><script>
const summaries = <?= json_encode($summary, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
summaries.forEach((s,i)=>{const ctx=document.getElementById('chart'+i);if(!ctx)return;new Chart(ctx,{type:s.type==='text'||s.type==='textarea'?'bar':'doughnut',data:{labels:s.labels,datasets:[{data:s.values}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},scales:(s.type==='text'||s.type==='textarea')?{y:{beginAtZero:true,ticks:{precision:0}}}:undefined}});});
</script></body></html>
